var solid_default = "---\nlayout: article\ntitle: Start with Solid\ndescription: Build Solid apps with Appwrite and learn how to use our powerful backend to add authentication, user management, file storage, and more.\ndifficulty: beginner\nreadtime: 3\nback: /docs/quick-starts\n---\n\nLearn how to setup your first Solid project powered by Appwrite.\n\n{% section #step-1 step=1 title=\"Create project\" %}\nHead to the [Appwrite Console](https://cloud.appwrite.io/console).\n\n{% only_dark %}\n![Create project screen](/images/docs/quick-starts/dark/create-project.avif)\n{% /only_dark %}\n\n{% only_light %}\n![Create project screen](/images/docs/quick-starts/create-project.avif)\n{% /only_light %}\n\nIf this is your first time using Appwrite, create an account and create your first project.\n\nThen, under **Add a platform**, add a **Web app**. The **Hostname** should be `localhost`.\n\n{% partial file=\"note-on-cors.md\" /%}\n\n{% only_dark %}\n![Add a platform](/images/docs/quick-starts/dark/add-platform.avif)\n{% /only_dark %}\n\n{% only_light %}\n![Add a platform](/images/docs/quick-starts/add-platform.avif)\n{% /only_light %}\n\nYou can skip optional steps.\n{% /section %}\n\n{% section #step-2 step=2 title=\"Create Solid project\" %}\nCreate a Vite project.\n\n```sh\nnpm create vite@latest my-app -- --template solid && cd my-app\n```\n{% /section %}\n\n{% section #step-3 step=3 title=\"Install Appwrite\" %}\nInstall the JavaScript Appwrite SDK.\n\n```sh\nnpm install appwrite\n```\n{% /section %}\n\n{% section #step-4 step=4 title=\"Import Appwrite\" %}\nFind your project's ID in the **Settings** page.\n\n{% only_dark %}\n![Project settings screen](/images/docs/quick-starts/dark/project-id.avif)\n{% /only_dark %}\n\n{% only_light %}\n![Project settings screen](/images/docs/quick-starts/project-id.avif)\n{% /only_light %}\n\nCreate a new file `src/lib/appwrite.js` and add the following code to it, replace `<PROJECT_ID>` with your project ID.\n\n```client-web\nimport { Client, Account } from 'appwrite';\n\nexport const client = new Client();\n\nclient\n    .setEndpoint('https://<REGION>.cloud.appwrite.io/v1')\n    .setProject('<PROJECT_ID>'); // Replace with your project ID\n\nexport const account = new Account(client);\nexport { ID } from 'appwrite';\n```\n{% /section %}\n\n{% section #step-5 step=5 title=\"Create a login page\" %}\nAdd the following code to `src/App.jsx`.\n\n```client-web\nimport { createSignal } from 'solid-js'\nimport { account, ID } from './lib/appwrite';\n\nconst App = () => {\n    const [loggedInUser, setLoggedInUser] = createSignal(null);\n    const [email, setEmail] = createSignal('');\n    const [password, setPassword] = createSignal('');\n    const [name, setName] = createSignal('');\n\n    async function login(email, password) {\n        await account.createEmailPasswordSession({\n            email,\n            password\n        });\n        setLoggedInUser(await account.get());\n    }\n\n    async function register(email, password, name) {\n        await account.create({\n            userId: ID.unique(),\n            email,\n            password,\n            name\n        });\n        login(email, password);\n    }\n\n    async function logout() {\n        await account.deleteSession({ sessionId: 'current' });\n        setLoggedInUser(null);\n    }\n\n    if (loggedInUser()) {\n        return (\n            <div>\n                <p>Logged in as {loggedInUser().name}</p>\n                <button onClick={logout}>Logout</button>\n            </div>\n        );\n    }\n\n    return (\n        <div>\n            <p>Not logged in</p>\n            <form>\n                <input type=\"email\" placeholder=\"Email\" value={email()} onChange={e => setEmail(e.target.value)} />\n                <input type=\"password\" placeholder=\"Password\" value={password()} onChange={e => setPassword(e.target.value)} />\n                <input type=\"text\" placeholder=\"Name\" value={name()} onChange={e => setName(e.target.value)} />\n                <button type=\"button\" onClick={() => login(email(), password())}>\n                    Login\n                </button>\n                <button type=\"button\" onClick={() => register(email(), password(), name())}>\n                    Register\n                </button>\n            </form>\n        </div>\n    );\n};\n\nexport default App;\n```\n{% /section %}\n\n{% section #step-6 step=6 title=\"All set\" %}\nRun your project with `npm run dev -- --open --port 3000` and open [Localhost on Port 3000](http://localhost:3000) in your browser.\n{% /section %}\n";
export { solid_default as default };
